  ('e1000000-0000-4000-a000-000000000a99', 'EM-BIO-00083', 5, 168, 'enem', 3, 1, 2026, 'multiple_choice', 'Cadeias alimentares e energia', 'Na cadeia milho → rato → cobra → gavião, os produtores fixam 1.000.000 kcal. Considerando que só cerca de 10% da energia passa de um nível trófico para o seguinte, quanta energia chega a(o) cobra?', 'Cada passagem mantém cerca de 10%: milho: 1.000.000 kcal → rato: 100.000 kcal → cobra: 10.000 kcal. O resto se perde como calor e nas atividades vitais.', 'Divida por 10 a cada nível que você avança na cadeia.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-000000000a9a', 'EM-BIO-00084', 5, 168, 'enem', 3, 1, 2026, 'multiple_choice', 'Cadeias alimentares e energia', 'Na cadeia algas → pequenos crustáceos → peixes → garças, os produtores fixam 10.000 kcal. Considerando que só cerca de 10% da energia passa de um nível trófico para o seguinte, quanta energia chega a(o) garças?', 'Cada passagem mantém cerca de 10%: algas: 10.000 kcal → pequenos crustáceos: 1.000 kcal → peixes: 100 kcal → garças: 10 kcal. O resto se perde como calor e nas atividades vitais.', 'Divida por 10 a cada nível que você avança na cadeia.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-000000000a9b', 'EM-BIO-00085', 5, 168, 'enem', 3, 1, 2026, 'multiple_choice', 'Cadeias alimentares e energia', 'Na cadeia folhas → lagarta → pássaro → gato-do-mato, os produtores fixam 10.000 kcal. Considerando que só cerca de 10% da energia passa de um nível trófico para o seguinte, quanta energia chega a(o) pássaro?', 'Cada passagem mantém cerca de 10%: folhas: 10.000 kcal → lagarta: 1.000 kcal → pássaro: 100 kcal. O resto se perde como calor e nas atividades vitais.', 'Divida por 10 a cada nível que você avança na cadeia.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-000000000a9c', 'EM-BIO-00086', 5, 168, 'enem', 3, 1, 2026, 'multiple_choice', 'Cadeias alimentares e energia', 'Na cadeia milho → rato → cobra → gavião, os produtores fixam 20.000 kcal. Considerando que só cerca de 10% da energia passa de um nível trófico para o seguinte, quanta energia chega a(o) cobra?', 'Cada passagem mantém cerca de 10%: milho: 20.000 kcal → rato: 2.000 kcal → cobra: 200 kcal. O resto se perde como calor e nas atividades vitais.', 'Divida por 10 a cada nível que você avança na cadeia.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-000000000a9d', 'EM-BIO-00087', 5, 168, 'enem', 3, 1, 2026, 'multiple_choice', 'Cadeias alimentares e energia', 'Na cadeia milho → rato → cobra → gavião, os produtores fixam 1.000.000 kcal. Considerando que só cerca de 10% da energia passa de um nível trófico para o seguinte, quanta energia chega a(o) gavião?', 'Cada passagem mantém cerca de 10%: milho: 1.000.000 kcal → rato: 100.000 kcal → cobra: 10.000 kcal → gavião: 1.000 kcal. O resto se perde como calor e nas atividades vitais.', 'Divida por 10 a cada nível que você avança na cadeia.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
